 @FXML private Label nameLabel,metaLabel,statusLabel,avatarLabel,sideAvatarLabel,sideNameLabel,sideMetaLabel,overviewStatusValue,overviewTitleValue,overviewCollegeValue,overviewEmployedValue,selectedTeacherCountLabel,adminWorkspaceTitle; @FXML private GridPane baseGrid,jobGrid,contactGrid; @FXML private Button editButton,jobEditButton,contactEditButton,editExperienceButton,deleteExperienceButton,exportTeachersButton,managementNavButton,maintenanceNavButton; @FXML private TabPane tabs; @FXML private Tab overviewTab,detailTab,experienceTab,adminTab,reviewTab; @FXML private VBox overviewPane,baseSection,jobSection,contactSection,experienceCardContainer; @FXML private Pane detailPane; @FXML private ScrollPane detailScroll; @FXML private TableView<Teacher> teacherTable; @FXML private TableColumn<Teacher,Void> selectCol,actionCol; @FXML private TableColumn<Teacher,String> idCol,nameCol,collegeCol,departmentCol,titleCol,statusCol; @FXML private TableView<TeacherChangeRequest> requestTable; @FXML private TableColumn<TeacherChangeRequest,String> requestTeacherCol,requestSubmitCol,requestStatusCol,requestReviewCol;
 private final TeacherClientService service=new TeacherClientService();private final Gson gson=new Gson();private TeacherOverviewVO overview;private final List<Control> editableControls=new ArrayList<>();private boolean editing,adminMaintenanceMode;private TeacherWorkExperience selectedExperience;private Pane selectedExperienceCard;private List<Teacher> teachers=new ArrayList<>();private final Set<String> selectedTeacherIds=new LinkedHashSet<>();private CheckBox selectAllTeachers;
 private static final List<String> BASE=List.of("UID","teacherId","name","politicalStatus","nationality","gender","idType","idNumber","idIssueDate","birthDate","nativePlace","householdType","birthPlace","sourcePlace","registeredResidence","partyMember","partyJoinDate","healthStatus");
